#!/bin/bash

echo "Do publish Factory"
curl -k -X 'POST' \
   '${GRAPE_API_URL:-https://localhost:8010}/api/rest/transactions' \
   -H 'accept: application/json' \
   -H 'Authorization: Basic ${GRAPE_API_AUTH:?set GRAPE_API_AUTH (base64 user:pass)}' \
   -H 'Content-Type: application/json' \
   -d '{ "encodedTx": ""
}'


echo "Do Create first account"

curl -k -X 'POST' \
   '${GRAPE_API_URL:-https://localhost:8010}/api/rest/transactions' \
   -H 'accept: application/json' \
   -H 'Authorization: Basic ${GRAPE_API_AUTH:?set GRAPE_API_AUTH (base64 user:pass)}'  \
   -H 'Content-Type: application/json' \
   -d '{ "encodedTx": ""
}'


echo "Do Create second account"

curl -k -X 'POST' \
   '${GRAPE_API_URL:-https://localhost:8010}/api/rest/transactions' \
   -H 'accept: application/json' \
   -H 'Authorization: Basic ${GRAPE_API_AUTH:?set GRAPE_API_AUTH (base64 user:pass)}'  \
   -H 'Content-Type: application/json' \
   -d '{ "encodedTx": ""
}'


echo "Check first account"

curl -k -H 'Authorization: Basic ${GRAPE_API_AUTH:?set GRAPE_API_AUTH (base64 user:pass)}'  "${GRAPE_API_URL:-https://localhost:8010}/api/rest/contracts/0xf6dcfb9812852b8b005becd3ac2d4e28f92df7f9/methods/0xf2a40db8?params=0x00"


echo "Check second account"

curl -k  -H 'Authorization: Basic ${GRAPE_API_AUTH:?set GRAPE_API_AUTH (base64 user:pass)}'  "${GRAPE_API_URL:-https://localhost:8010}/api/rest/contracts/0xf6dcfb9812852b8b005becd3ac2d4e28f92df7f9/methods/0xf2a40db8?params=0x01"


